 if cid.startswith('RSI') and '_xup_' in cid:
  period,threshold=cid[3:].split('_xup_');return f'القوة النسبية {period}، عبور {threshold} صعودًا'
 prefixes=[('VolSpike','طفرة الحجم بحسب الانحراف المعياري'),('WilliamsR','مذبذب وليامز، عبور صاعد من التشبع البيعي'),('RSI','القوة النسبية، انحراف صاعد'),('EMA','تقاطع متوسطات أسية'),('PX_x_EMA','عبور السعر فوق المتوسط الأسي'),('BB','عودة داخل نطاق بولنجر'),('Donchian','إشارة نطاق دونشيان'),('TakerRatio','نسبة شراء الآخذين'),('Stoch','عبور ستوكاستك صعودًا'),('Aroon','تقاطع أرون صاعد'),('MACD','تقاطع ماكد صاعد'),('MFI','تدفق الأموال'),('CCI','مؤشر قناة السلع'),('VWAP','السعر المرجح بالحجم'),('VZ','انحراف الحجم'),('OBV','الحجم المتراكم'),('BullEngulfing','شمعة ابتلاع صاعد'),('Hammer','شمعة مطرقة'),('FVG','فجوة سعرية ثلاثية الشموع')]
 return next((label for prefix,label in prefixes if cid.startswith(prefix)), 'إعداد الإشارة المسجل')
